def count_net(layers):
    total = 0
    for layer in layers:
        if layer[0] == 'conv':
            _, c_in, c_out, k = layer
            total += c_out * (c_in * k * k + 1)
        elif layer[0] == 'dense':
            _, n_in, n_out = layer
            total += n_in * n_out + n_out
    return total

